 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # Change the middle of every horizontal three-cell pattern A, background, A
    # where A is a non-background symbol.
    vals = [v for row in grid for v in row]
    bg = max(set(vals), key=vals.count)
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c] == bg and row[c - 1] == row[c + 1] and row[c - 1] != bg:
                out[r][c] = 2
    return out
